head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf70000";
scwin.fn_chkModYn = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.fn_chkModYn = scwin.tx_fn_chkModYn;
        scwin.init_recvParam();
        scwin.init_ctxDefaults();
        await scwin.init_rowCopy();
        scwin.init_conds();
        await scwin.init_loadList();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf70000.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다. 진입 기본값 충전 — 파라미터로 안 온 키에 스펙 기본값(조건 평가보다 먼저).
 * @returns {void}
 * @hidden N
 */
scwin.init_ctxDefaults = function () {
    const cds = {"authYn":"Y"};
    const pc0 = $c.util.getComponent("dma_pageContext");
    if (!pc0 || !pc0.get || !pc0.set) { return; }
    for (let ck in cds) { const cv0 = pc0.get(ck); if (cv0 === undefined || cv0 === null || cv0 === '') { pc0.set(ck, cds[ck]); } }
};

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — pageContext.ldMktTpCd, pageContext.psDepCd, ldMktTpCd, usrLdMktTpCd, pageContext.usrTpCd, page

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_ldMktTpCd", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610'); } }, { id: "if_ldMktTpCd_2", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410'); } }, { id: "if_ldMktTpCd_3", fn: function(){ return ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '2'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrLdMktTpCd") ?? "") === '6'); } }, { id: "if_usrLdMktTpCd", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrLdMktTpCd_3", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") !== '1'); } }, { id: "if_usrTpCd_2", fn: function(){ return ((dma_pageContext.get("usrTpCd") ?? "") === '1'); } }, { id: "if_page", fn: function(){ return (!(String(((dma_pageContext.get("page") ?? "")) === null ? '' : ((dma_pageContext.get("page") ?? ""))).length === 0)); } }, { id: "if_authYn_2", fn: function(){ return (((dma_pageContext.get("ldMktTpCd") ?? "") === '1' && (dma_pageContext.get("psDepCd") ?? "") === '2610') || ((dma_pageContext.get("ldMktTpCd") ?? "") === '2' && (dma_pageContext.get("psDepCd") ?? "") === '3410') || ((dma_pageContext.get("ldMktTpCd") ?? "") !== '1' && (dma_pageContext.get("ldMktTpCd") ?? "") !== '2')); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        const ok = !!b.fn();
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_integSrchNo", fn: function () { return String(String((dma_pageContext.get("integSrchNo") ?? ""))); } },
        { childId: "ipt_formatKeywrd", fn: function () { return String(String((dma_pageContext.get("formatKeywrd") ?? ""))); } },
        { childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("totalSize") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("pageIndex") ?? ""))) + "/" + String(dma_page.get("pageCount")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        setCommonSelect("ldMktTpCd");

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.onpageload' }); }
};

/**
 * @method
 * @name init_loadList
 * @description 초기 목록 조회 — as-is 는 진입 자체가 조회였다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_loadList = async function () {
    // 초기 목록 — as-is 는 진입 자체가 조회였다(근거: self_action). 진입점 합성이 이 단계를 잇는다.
    await scwin.tx_load_list();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name headerKeywrdForm_onsubmit
 * @description headerKeywrdForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.headerKeywrdForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.headerKeywrdForm_onsubmit' }); }
};

/**
 * @method
 * @name input_25_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_25_onclick = function(e){
    try {
        openKeywrdList()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.input_25_onclick' }); }
};

/**
 * @method
 * @name input_27_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.input_27_onclick = function(e){
    try {
        searchIntegSrch()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.input_27_onclick' }); }
};

/**
 * @method
 * @name fn_70000Table_oncellclick
 * @description fn_70000Table 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fn_70000Table_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_resultList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_resultList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: clickTr (인자 미해석) · fn_chkModYn (인자 미해석) */
        scwin.search_detail(r["integSrchNo"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: '70000Table.oncellclick' });
    }
};

/**
 * @method
 * @name btn_searchDetail_onclick
 * @description 「등록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_searchDetail_onclick = function(e){
    try {
        scwin.search_detail('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.btn_searchDetail_onclick' }); }
};

/**
 * @method
 * @name __on_enter_2_ipt_formatkeywrd
 * @description on enter 2 ipt formatkeywrd 처리
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.__on_enter_2_ipt_formatkeywrd = function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ searchIntegSrch() }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf70000.__on_enter_2_ipt_formatKeywrd' }); }
};

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name krxpage_pagenavigator_111_onclick
 * @description krxpage_pagenavigator_111 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_111_onclick = async function (index) { const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index; try { $c.util.getComponent('dma_loadListReq').set('pageIndex', pi); } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'krxpage_pagenavigator_111.page' }); } await scwin.tx_load_list(); };

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_srchInteg
 * @description srch Integ 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_srchInteg = async function () {
    const sbmOptions = {
        id: "tx_fn_srchInteg",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_srchIntegReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_chkModYn
 * @description chk Mod Yn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_chkModYn = async function () {
    const sbmOptions = {
        id: "tx_fn_chkModYn",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_chkModYnReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_load_list
 * @description load list 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/ods/integsrch.do",
        ref: "dma_loadListReq",
        target: "dlt_chrgInstIsList=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf70000.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    const rj = res && res.responseJSON;
    const tot = rj && (rj["pageCount"] !== null ? rj["pageCount"] : (rj.body && rj.body["pageCount"]));
    if (tot !== null && tot !== "") {
        $c.util.getComponent("krxpage_pagenavigator_111").setCount(Math.ceil(Number(tot) / 10));
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fn_70000Table_fmt_column2
 * @description 70000 Table fmt column2 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {*} r r
 * @param {*} c c
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fn_70000Table_fmt_column2 = async function (data, formattedData, r, c) {
    try {
        const dl = $c.util.getComponent("dlt_resultList");
        const v = String(dl && dl.getCellData ? (dl.getCellData(r, "type") ?? '') : '');
        if (v === 'A') { return "키워드"; }
        return '';
    } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: "70000Table.column2" }); return String(data ?? ''); }
};

/**
 * @method
 * @name search_detail
 * @description search detail 처리
 * @param {*} ipt_integSrchNo ipt_integSrchNo
 * @returns {void}
 * @hidden N
 */
scwin.search_detail = function (ipt_integSrchNo) {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CreateDialogFrame
    const url = "/ods/integsrch.do?integSrchNo=" + ipt_integSrchNo + "&method=searchDetailForm&SCREN_ID=JLDODS70010.jsp&SCREN_PROCES_TP_CD=01";
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.frame.CreateDialogFrame("", (function (__u) { const __s = String(__u === null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url), "상세내용", { width: 1200, height: 800 }, {});
};

/**
 * @method
 * @name srchInteg
 * @description srch Integ 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.srchInteg = async function () {
    await scwin.tx_fn_srchInteg();
};

/**
 * @method
 * @name setKeywrd
 * @description set Keywrd 처리
 * @param {*} keywrd keywrd
 * @returns {void}
 * @hidden N
 */
scwin.setKeywrd = function (keywrd) {
    $c.util.getComponent('ipt_formatKeywrd').setValue(keywrd);
};
